import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const v=JSON.parse('{"title":"ADR 002 · Retrieval storage","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/002-retrieval-storage.md","filePath":"decisions/002-retrieval-storage.md","lastUpdated":1794376220000}'),n={name:"decisions/002-retrieval-storage.md"};function o(s,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-002-·-retrieval-storage" tabindex="-1">ADR 002 · Retrieval storage <a class="header-anchor" href="#adr-002-·-retrieval-storage" aria-label="Permalink to &quot;ADR 002 · Retrieval storage&quot;">​</a></h1><p><strong>Status:</strong> Under evaluation. <strong>Date:</strong> November 5, 2026.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The system needs BM25, vector similarity, and relationship-guided evidence retrieval over a changing corpus. The desired scale and write rate are not yet specified.</p><h2 id="candidate-design" tabindex="-1">Candidate design <a class="header-anchor" href="#candidate-design" aria-label="Permalink to &quot;Candidate design&quot;">​</a></h2><p>Co-locate SQLite retrieval with a Rust service. Use ordinary tables for source revisions, chunks, identities, claims, and provenance; FTS5 for BM25; an evaluated vector extension; and indexed relationships for bounded graph traversal.</p><p>Expose vector/search capabilities explicitly. Preserve canonical IDs and evidence contracts so a dedicated vector or search service can replace an adapter without changing answer policy.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><p>A dedicated retrieval service can provide a different scaling, indexing, filtering, and replication model. A mixed deployment may retain SQLite metadata while externalizing a measured bottleneck. Compare at equivalent retrieval quality and access scope; local storage alone does not establish superiority.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Standard SQLite WAL has one writer per database and same-host sharing requirements. The deployment needs a local index-publication owner, short transactions, bounded database work, checkpoint policy, and an explicit backup/recovery design. Multiple hosts need evaluated ownership and replication behavior. Broker events are notifications, not file replication.</p><h2 id="selection-gates" tabindex="-1">Selection gates <a class="header-anchor" href="#selection-gates" aria-label="Permalink to &quot;Selection gates&quot;">​</a></h2><p>Test filtered recall and latency, exact-versus-ANN behavior, simultaneous ingestion and chat, graph fanout, memory, crash recovery, extension migrations, and source-version consistency. Pin and validate the extension&#39;s native build and transactional behavior. See <a href="/knowledge-lab/architecture/retrieval">hybrid retrieval</a>.</p>',13)])])}const u=a(n,[["render",o]]);export{v as __pageData,u as default};
